// MCP tools for batch 48 (31-Oct-2026): design-system + brand tools for the AI era.
// Pure cores come from src/tools_core48.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/*) — one source of
// truth with the /tools/ pages. design_md_from_references reads D1 (public library items only); search_icons fetches pinned
// @iconify-json files from jsDelivr (free CDN, cached per isolate + in the Cache API). No paid APIs.
import { MGDTypeScale, MGDColorScale, MGDContrast, MGDOklch, MGDTokens, MGDIcons, MGDScreens, MGDBrand, MGDSlogan } from "./tools_core48.js";
import { MGDRoles } from "./design_core.js";
import { lint as dmdLint } from "./designmd_lint.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => (structuredContent ? { content: [{ type: "text", text }], structuredContent } : { content: [{ type: "text", text }] });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const int = (x, d, lo, hi) => { const n = parseInt(x, 10); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
const numIn = (x, d, lo, hi) => { const n = Number(x); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
const RO = (title, open) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: !!open });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const list = (x, max) => (Array.isArray(x) ? x : typeof x === "string" ? x.split(/[\n,;]+|\s{2,}|\s(?=#)/) : []).map((s) => str(s, 80).trim()).filter(Boolean).slice(0, max);
const COLOR_LIST = { description: "Colours as an array of CSS colour strings, or one string (comma/newline separated). HEX, rgb(), hsl(), oklch(), names.", anyOf: [{ type: "array", items: { type: "string" } }, { type: "string" }] };

const RATIO_NAMES = Object.keys(MGDTypeScale.RATIOS || {});
const FORMATS_SCALE = ["css", "tailwind_v4", "dtcg", "table"];

