// ---------------------------------------------------------------------------------------------------------------------
function typeScale(a) {
  const ratio = typeof a.ratio === "string" && !/^[\d.]+$/.test(a.ratio) ? (RATIO_NAMES.includes(a.ratio) ? a.ratio : null) : numIn(a.ratio, 1.2, 1.01, 3);
  if (ratio === null) return err(`Unknown ratio "${str(a.ratio, 40)}". Use a number or one of: ${RATIO_NAMES.join(", ")}.`);
  const base = numIn(a.base_px, 16, 8, 40);
  const o = { base_px: base, ratio, steps_up: int(a.steps_up, 6, 0, 10), steps_down: int(a.steps_down, 2, 0, 5), unit: a.unit === "px" ? "px" : "rem", names: a.names === "step" ? "step" : "tailwind" };
  if (a.fluid) {
    o.fluid = { min_vw: numIn(a.min_vw, 375, 200, 2000), max_vw: numIn(a.max_vw, 1200, 400, 4000), min_base: base, max_base: numIn(a.max_base_px, base * 1.125, 8, 60) };
    if (a.max_ratio != null) o.fluid.max_ratio = typeof a.max_ratio === "string" && RATIO_NAMES.includes(a.max_ratio) ? a.max_ratio : numIn(a.max_ratio, 1.25, 1.01, 3);
    if (o.fluid.max_vw <= o.fluid.min_vw) return err("max_vw must be larger than min_vw.");
  }
  const r = MGDTypeScale.scale(o);
  const want = Array.isArray(a.formats) && a.formats.length ? a.formats.filter((f) => FORMATS_SCALE.includes(f)) : FORMATS_SCALE;
  const parts = [`Type scale: base ${base}px × ${typeof ratio === "string" ? ratio : ratio}${o.fluid ? `, fluid ${o.fluid.min_vw}–${o.fluid.max_vw}px viewport (base ${base}→${r2(o.fluid.max_base)}px)` : ""}, ${r.steps.length} sizes.`];
  if (want.includes("table")) parts.push(r.table);
  if (want.includes("css")) parts.push("CSS custom properties:\n" + fence("css", r.css));
  if (want.includes("tailwind_v4")) parts.push("Tailwind v4 (paste into your CSS):\n" + fence("css", r.tailwind_v4));
  if (want.includes("dtcg")) parts.push("W3C DTCG 2025.10 tokens:\n" + fence("json", JSON.stringify(r.dtcg, null, 2)));
  parts.push(`Preview and tweak it: ${T}/type-scale-generator/ · fluid clamp() values: ${T}/clamp-calculator/`);
  return ok(parts.join("\n\n"), { settings: r.settings, steps: r.steps });
}
const r2 = (n) => Math.round(n * 100) / 100;

function colorScale(a) {
  let input = a.colors;
  if (Array.isArray(input)) input = input.slice(0, 12);
  else if (input && typeof input === "object") input = Object.fromEntries(Object.entries(input).slice(0, 12));
  else input = str(input, 1000);
  if (!input || (Array.isArray(input) && !input.length)) return err("Pass colors, e.g. \"#2563eb\" or {\"brand\": \"#2563eb\"}.");
  let p;
  try { p = MGDColorScale.palette(input, { mode: a.keep_color === false ? "fit" : "keep", anchor: a.anchor ? str(a.anchor, 4) : "auto" }); }
  catch (e) { return err("Couldn't read those colours: " + str(e && e.message, 200)); }
  if (!p.palettes || !p.palettes.length) return err("No valid colours found. Use HEX (#2563eb), rgb(), hsl() or oklch().");
  const want = Array.isArray(a.formats) && a.formats.length ? a.formats : ["tailwind_v4", "css"];
  const parts = [];
  for (const pal of p.palettes) {
    parts.push(`**${pal.name}** (input ${pal.input}, kept at step ${pal.base_step}):\n\n| Step | HEX | OKLCH | vs white | vs black | Text |\n|---|---|---|---|---|---|\n` +
      pal.steps.map((s) => `| ${s.label}${s.is_base ? " ★" : ""} | \`${s.hex}\` | \`${s.oklch}\` | ${s.contrast_white} | ${s.contrast_black} | ${s.best_text === "#ffffff" ? "white" : "black"} |`).join("\n"));
  }
  const W = { tailwind_v4: ["Tailwind v4 @theme", "css"], css: ["CSS variables", "css"], tailwind_v3: ["Tailwind v3 config", "js"], json: ["JSON", "json"], dtcg: ["W3C DTCG 2025.10", "json"] };
  for (const f of want) if (W[f] && p[f] != null) parts.push(W[f][0] + ":\n" + fence(W[f][1], typeof p[f] === "string" ? p[f] : JSON.stringify(p[f], null, 2)));
  parts.push(`Edit the ramps visually: ${T}/tailwind-color-generator/`);
  return ok(parts.join("\n\n"), { palettes: p.palettes.map((x) => ({ name: x.name, input: x.input, base_step: x.base_step, steps: x.steps.map((s) => ({ step: s.step, hex: s.hex, oklch: s.oklch, contrast_white: s.contrast_white, contrast_black: s.contrast_black })) })) });
}

function contrast(a) {
  const target = [3, 4.5, 7].includes(Number(a.target)) ? Number(a.target) : 4.5;
  const yes = (b) => (b ? "✅ pass" : "❌ fail");
  if (a.foreground && a.background) {
    let c;
    try { c = MGDContrast.check(str(a.foreground, 80), str(a.background, 80)); } catch (e) { return err("Couldn't read those colours: " + str(e && e.message, 200)); }
    if (!c || c.ratio == null) return err("Couldn't read those colours. Use HEX, rgb(), hsl(), oklch() or a colour name.");
    const lines = [`${c.fg} on ${c.bg}: **${c.ratio_label}**${c.composited ? " (alpha composited)" : ""}`, "",
      "| WCAG 2.2 check | Needs | Result |", "|---|---|---|",
      `| AA normal text | 4.5:1 | ${yes(c.aa_normal)} |`, `| AA large text (24px, or 18.66px bold) | 3:1 | ${yes(c.aa_large)} |`,
      `| AAA normal text | 7:1 | ${yes(c.aaa_normal)} |`, `| AAA large text | 4.5:1 | ${yes(c.aaa_large)} |`, `| UI components & graphics (1.4.11) | 3:1 | ${yes(c.ui_3to1)} |`];
    let fix = null;
    if (c.ratio_exact < target) {
      fix = MGDContrast.fix(str(a.foreground, 80), str(a.background, 80), target, { keep: "hue" });
      if (fix && fix.ok) lines.push("", `Nearest passing foreground for ${target}:1 (same hue, ${fix.direction}): \`${fix.hex}\` (\`${fix.oklch}\`) = ${fix.ratio}:1.`);
      else if (fix) lines.push("", `No lightness of this hue reaches ${target}:1 on this background; best is \`${fix.hex}\` = ${fix.ratio}:1. Change the background or the hue.`);
    }
    lines.push("", `Check more pairs visually: ${T}/contrast-checker/`);
    return ok(lines.join("\n"), { ...c, fix });
  }
  const cols = list(a.colors, 64);
  if (cols.length < 2) return err("Pass foreground + background, or colors with at least 2 colours for a matrix.");
  let m;
  try { m = MGDContrast.matrix(cols); } catch (e) { return err("Couldn't read those colours: " + str(e && e.message, 200)); }
  const hexes = m.colors.map((c) => c.hex || c);
  const head = `| | ${hexes.map((h) => "`" + h + "`").join(" | ")} |\n|---|${hexes.map(() => "---").join("|")}|`;
  const rows = m.grid.map((row, i) => `| \`${hexes[i]}\` | ${row.map((v, j) => (i === j ? "—" : (typeof v === "object" ? v.ratio : v) + (Number(typeof v === "object" ? v.ratio : v) >= 4.5 ? " ✅" : Number(typeof v === "object" ? v.ratio : v) >= 3 ? " ◐" : ""))).join(" | ")} |`).join("\n");
  const s = m.summary;
  const text = `Contrast matrix for ${hexes.length} colours (✅ ≥ 4.5 AA text, ◐ ≥ 3 large text/UI):\n\n${head}\n${rows}\n\n${s.aa_normal} of ${s.total} pairs pass AA for normal text, ${s.aa_large} for large text/UI, ${s.aaa_normal} reach AAA.\n\nCheck more pairs visually: ${T}/contrast-checker/`;
  return ok(text, { colors: hexes, pairs: m.pairs, summary: s });
}

function convertColor(a) {
  const raw = Array.isArray(a.colors) ? a.colors.map((x) => str(x, 120)).filter(Boolean).slice(0, 50) : (MGDOklch.extract(str(a.colors, 6000)) || []).slice(0, 50);
  if (!raw.length) return err("Pass colors, e.g. \"#2563eb\" or [\"oklch(70% 0.25 150)\", \"rgb(0 128 255)\"].");
  const prec = ["compact", "default", "full"].includes(a.precision) ? a.precision : "default";
  const rows = raw.map((c) => { try { return MGDOklch.convert(c, { precision: prec }); } catch (e) { return { input: c, ok: false, error: String(e && e.message) }; } });
  const one = (r) => r.ok ? [
    `**${r.input}**`, `- HEX \`${r.hex}\`${r.in_srgb ? "" : ` (gamut-mapped from outside sRGB; naive clip would be ${r.hex_clipped})`}`,
    `- OKLCH \`${r.css.oklch}\` · OKLab \`${r.css.oklab}\``, `- RGB \`${r.css.rgb}\` · HSL \`${r.css.hsl}\``,
    `- Display P3 \`${r.css.p3}\` · in sRGB: ${r.in_srgb ? "yes" : "no"} · in P3: ${r.in_p3 ? "yes" : "no"}`,
    `- CMYK (naive, not colour-managed) ${r.cmyk.c}/${r.cmyk.m}/${r.cmyk.y}/${r.cmyk.k} · contrast vs white ${r2(r.contrast.white)}:1, vs black ${r2(r.contrast.black)}:1`,
    r.warnings && r.warnings.length ? `- note: ${r.warnings.join("; ")}` : null,
  ].filter(Boolean).join("\n") : `**${r.input}**: ${r.error || "couldn't read this colour"}`;
  const good = rows.filter((r) => r.ok);
  const fb = good.length === 1 && good[0].css.fallback ? "\n\nCSS with fallback:\n" + fence("css", good[0].css.fallback) : "";
  const text = rows.map(one).join("\n\n") + fb + `\n\nPick OKLCH colours visually (sRGB/P3 gamut shown): ${T}/oklch-color-picker/ · ${T}/hex-to-oklch/ · ${T}/oklch-to-hex/`;
  return ok(text, { colors: rows.map((r) => r.ok ? { input: r.input, hex: r.hex, oklch: r.oklch, css: r.css, in_srgb: r.in_srgb, in_p3: r.in_p3, rgb: r.rgb, hsl: r.hsl, cmyk: r.cmyk } : { input: r.input, error: r.error || "invalid" }) });
}

// ---- shadcn theme + tokens -----------------------------------------------------------------------------------------
function roleMap(o) { const out = {}; if (o && typeof o === "object") for (const k of MGDRoles.ROLES) { const h = MGDRoles.normHex(String(o[k] || "")); if (h) out[k] = h; } return out; }
function shadcnTheme(a) {
  const o = { fix: true };
  if (a.colors && typeof a.colors === "object") { const L = roleMap(a.colors.light), D = roleMap(a.colors.dark); if (Object.keys(L).length) o.roles = { light: L, dark: Object.keys(D).length ? D : undefined }; }
  if (a.brand_color) { const p = MGDOklch.convert(str(a.brand_color, 80)); if (!p.ok) return err("brand_color: " + (p.error || "not a colour")); o.primary = p.hex; }
  if (!o.primary && !o.roles) o.primary = "#2563eb";
  if (!o.primary && o.roles) o.primary = o.roles.light.primary;
  if (a.accent) { const ac = str(a.accent, 40); o.accent = ac === "none" || ac === "tint" ? ac : (MGDOklch.convert(ac).ok ? MGDOklch.convert(ac).hex : "none"); }
  if (a.neutral) o.neutral = str(a.neutral, 12);
  if (a.radius != null) o.radius = numIn(a.radius, 0.625, 0, 2);
  if (a.charts) o.charts = str(a.charts, 20);
  o.level = a.level === "AAA" ? "AAA" : "AA";
  const t = MGDTokens.shadcnTheme(o);
  const out = ["v4", "v3", "registry", "all"].includes(a.output) ? a.output : "v4";
  const textFails = t.contrast.filter((c) => !c.pass && !c.advisory);
  const parts = [`shadcn/ui theme from ${o.primary} (neutral ${t.neutral}, radius ${t.radiusRem || t.radius}, ${t.level}): ${t.contrast.length} contrast pairs checked, ${textFails.length} failing${t.fixed && t.fixed.length ? `, ${t.fixed.length} auto-fixed by lightness (hue kept)` : ""}.`];
  if (t.notes && t.notes.length) parts.push(t.notes.slice(0, 6).map((n) => "- " + n).join("\n"));
  if (out === "v4" || out === "all") parts.push("app/globals.css (Tailwind v4, shadcn/ui):\n" + fence("css", t.css_v4));
  if (out === "v3" || out === "all") parts.push("globals.css (Tailwind v3, HSL):\n" + fence("css", t.css_v3) + (t.config_v3 ? "\ntailwind.config.js:\n" + fence("js", t.config_v3) : ""));
  if (out === "registry" || out === "all") parts.push("shadcn registry:theme JSON:\n" + fence("json", typeof t.registry === "string" ? t.registry : JSON.stringify(t.registry, null, 2)));
  const q = t.roles && t.roles.l ? `?l=${t.roles.l}${t.roles.d ? "&d=" + t.roles.d : ""}` : `?brand=${o.primary.slice(1)}`;
  parts.push(`Preview it on real components and tweak it: ${T}/shadcn-theme-generator/${q}`);
  const pick = (m) => Object.fromEntries(Object.entries(m).map(([k, v]) => [k, v.oklch]));
  return ok(parts.join("\n\n"), { light: pick(t.light), dark: pick(t.dark), radius: t.radiusRem || t.radius, contrast_failures: textFails.length, contrast: t.contrast.map((c) => ({ theme: c.theme, fg: c.fg, bg: c.bg, ratio: c.ratio, min: c.min, pass: c.pass })), roles: t.roles ? { light: t.roles.light, dark: t.roles.dark } : undefined });
}

const TOK_FMT = { dtcg: ["tokens.json (W3C DTCG 2025.10)", "json"], tailwind: ["Tailwind v4 theme.css", "css"], css: ["tokens.css", "css"], scss: ["_tokens.scss", "scss"], styleDictionary: ["Style Dictionary tokens.json", "json"] };
function exportTokens(a) {
  let model;
  const src = str(a.source, 200000);
  try {
    if (src.trim()) model = MGDTokens.parseAny(src);
    else if (a.colors && typeof a.colors === "object" && Object.keys(a.colors).length) {
      const cols = {}; for (const [k, v] of Object.entries(a.colors).slice(0, 16)) { const c = MGDOklch.convert(str(v, 80)); if (c.ok) cols[str(k, 30).toLowerCase().replace(/[^a-z0-9-]+/g, "-")] = c.hex; }
      if (!Object.keys(cols).length) return err("colors had no valid colour values.");
      model = MGDTokens.buildModel({ colors: cols });
    } else return err("Pass source (a DESIGN.md, shadcn CSS or palette JSON) or colors ({name: colour}).");
  } catch (e) { return err("Couldn't read the source: " + str(e && e.message, 300)); }
  if (!model) return err("Couldn't detect the source format (DESIGN.md with YAML front matter, shadcn/ui CSS variables, or palette JSON).");
  if (a.name) model.name = str(a.name, 60);
  const want = (Array.isArray(a.formats) && a.formats.length ? a.formats : ["dtcg", "tailwind"]).filter((f) => TOK_FMT[f]);
  const e = MGDTokens.exportTokens(model, want, { colorFormat: a.color_format === "hex" ? "hex" : "oklch" });
  const parts = [`${e.count} tokens from ${model.source || "your input"}${model.name ? ` (“${model.name}”)` : ""}.${e.warnings && e.warnings.length ? "\nWarnings:\n" + e.warnings.slice(0, 10).map((w) => "- " + w).join("\n") : ""}`];
  for (const f of want) if (e[f] != null) parts.push(TOK_FMT[f][0] + ":\n" + fence(TOK_FMT[f][1], typeof e[f] === "string" ? e[f] : JSON.stringify(e[f], null, 2)));
  parts.push(`Edit, preview and download all formats (zip): ${T}/design-tokens-generator/`);
  return ok(parts.join("\n\n"), { count: e.count, warnings: e.warnings, contrast: e.contrast });
}

// ---- icons (pinned iconify JSON from jsDelivr; parsed index kept per isolate) ---------------------------------------
const ICON_CACHE = { sets: {}, tags: null, index: {} };
async function getJson(url) {
  const r = await fetch(url, { cf: { cacheTtl: 604800, cacheEverything: true }, headers: { "user-agent": "mgd-inspiration-mcp" } });
  if (!r.ok) throw new Error(`HTTP ${r.status} for ${url}`);
  return r.json();
}
async function iconIndex(sets) {
  const key = sets.slice().sort().join(",");
  if (ICON_CACHE.index[key]) return ICON_CACHE.index[key];
  const cdn = "https://cdn.jsdelivr.net/npm/";
  await Promise.all(sets.map(async (s) => { if (!ICON_CACHE.sets[s]) ICON_CACHE.sets[s] = await getJson(cdn + MGDIcons.SETS[s].iconify + "/icons.json"); }));
  if (sets.includes("lucide") && !ICON_CACHE.tags) { try { ICON_CACHE.tags = await getJson(cdn + "lucide-static@1.57.0/tags.json"); } catch (_) { ICON_CACHE.tags = {}; } }
  const idx = MGDIcons.buildIndex(sets.map((s) => ICON_CACHE.sets[s]), MGDIcons.SYNONYMS, ICON_CACHE.tags ? { lucide: ICON_CACHE.tags } : undefined);
  ICON_CACHE.index[key] = idx;
  return idx;
}
async function searchIcons(a) {
  const q = str(a.query, 80).trim();
  if (!q) return err("Pass a query, e.g. 'delete' or 'arrow right'.");
  const sets = (Array.isArray(a.sets) && a.sets.length ? a.sets : ["lucide", "tabler", "heroicons"]).filter((s) => MGDIcons.SETS[s]);
  if (!sets.length) return err("sets must be lucide, tabler, heroicons and/or ph.");
  const fw = ["react", "vue", "svelte"].includes(a.framework) ? a.framework : "react";
  let idx;
  try { idx = await iconIndex(sets); } catch (e) { return err("Couldn't load the icon data from the CDN (" + str(e && e.message, 160) + ") — this is not a 'no results' answer; retry."); }
  const limit = int(a.limit, 8, 1, 24);
  const hits = MGDIcons.search(idx, q, { sets, style: a.style || "any", limit });
  if (!hits.length) return ok(`0 icons for "${q}" in ${sets.join(", ")}. Try a simpler word (e.g. 'trash' instead of 'remove item'), or browse: ${T}/svg-icons/`);
  const size = int(a.size, 24, 8, 512), stroke = numIn(a.stroke, 2, 0.5, 4);
  const rows = hits.map((h, i) => {
    const imp = MGDIcons.importName(h.set, h.name, fw);
    const svg = (a.svg === true || (a.svg !== false && i < 4)) ? MGDIcons.toSvg(ICON_CACHE.sets[h.set], h.name, { size, stroke }) : null;
    return { set: h.set, name: h.name, style: h.style, license: MGDIcons.SETS[h.set].license, import: imp ? imp.import : null, package: imp ? imp.package : null, component: imp ? imp.component : null, note: imp ? imp.note : `No official ${fw} package for this set — paste the SVG.`, svg };
  });
  const text = `${rows.length} icon(s) for "${q}" (${sets.join(", ")}; ${fw}). Import names are checked against the official packages — use them exactly:\n\n` +
    rows.map((r) => `• ${r.set}/${r.name}${r.style && r.style !== "outline" ? ` (${r.style})` : ""} — ${r.license}\n  ${r.import ? "`" + r.import + "`" : r.note}${r.note && r.import ? "\n  " + r.note : ""}${r.svg ? "\n" + fence("svg", r.svg) : ""}`).join("\n\n") +
    `\n\nBrowse, recolour and download SVG/PNG: ${T}/svg-icons/#q=${encodeURIComponent(q)}`;
  return ok(text, { icons: rows });
}

// ---- screen sizes ---------------------------------------------------------------------------------------------------
function screenSizes(a) {
  const rows = MGDScreens.query({ q: str(a.query, 60) || undefined, type: a.type || undefined, brand: str(a.brand, 30) || undefined, year_min: a.year_min ? int(a.year_min, 0, 1990, 2100) : undefined });
  const limit = int(a.limit, 25, 1, 60), sel = rows.slice(0, limit);
  if (!sel.length) return ok(`0 devices match. Try a broader query (e.g. 'iphone', 'galaxy', 'macbook') or a type filter. Full table: ${T}/screen-sizes/`);
  const f = (v) => (v == null ? "—" : Array.isArray(v) ? v.join(" × ") : String(v));
  const table = "| Device | Year | Viewport (CSS px) | Pixels | DPR | PPI | Diagonal | Safe area (top/bottom) |\n|---|---|---|---|---|---|---|---|\n" +
    sel.map((d) => `| ${d.name} | ${f(d.year)} | ${f(d.vp)} | ${f(d.px)} | ${f(d.dpr)} | ${f(d.ppi)} | ${d.diag ? d.diag + "″" : "—"} | ${d.safe ? `${d.safe.top} / ${d.safe.bottom}` : "—"} |`).join("\n");
  const parts = [`${sel.length} of ${rows.length} device(s), data checked ${MGDScreens.CHECKED} (blank = not published by the maker, not guessed):`, table];
  const ex = a.export;
  if (ex === "css") parts.push(fence("css", MGDScreens.toCss(sel, { mode: "devices" })));
  if (ex === "breakpoints") parts.push(fence("css", MGDScreens.toCss(sel, { mode: "breakpoints" })));
  if (ex === "tailwind") parts.push(fence("css", MGDScreens.toTailwind(sel)));
  if (ex === "figma") parts.push(fence("json", MGDScreens.toFigma(sel)));
  parts.push("Sources per device: " + T + "/screen-sizes/ (each row links its source).");
  return ok(parts.join("\n\n"), { devices: sel.map((d) => ({ id: d.id, name: d.name, brand: d.brand, type: d.type, year: d.year, viewport: d.vp, pixels: d.px, dpr: d.dpr, ppi: d.ppi, diagonal_in: d.diag, safe_area: d.safe, source: d.source })) });
}

// ---- brand board + slogans ------------------------------------------------------------------------------------------
function cleanSvg(x) {
  let v = str(x, 200000);
  if (!/^\s*(<\?xml[^>]*>\s*)?<svg[\s>]/i.test(v)) return null;
  v = v.replace(/<script[\s\S]*?<\/script>/gi, "").replace(/<foreignObject[\s\S]*?<\/foreignObject>/gi, "").replace(/\son[a-z]+\s*=\s*("[^"]*"|'[^']*')/gi, "")
    .replace(/(href|xlink:href)\s*=\s*("|')\s*(?!#|data:image\/)[^"']*\2/gi, "");
  return v;
}
function brandBoard(a) {
  const name = str(a.brand_name, 60).trim();
  if (!name) return err("Pass brand_name.");
  const cols = (Array.isArray(a.colors) ? a.colors : typeof a.colors === "string" ? a.colors.split(/[\s,]+/) : []).slice(0, 8).map((c, i) => {
    const hex = typeof c === "string" ? c : c && c.hex; const cv = MGDOklch.convert(str(hex, 80));
    return cv.ok ? { name: str(c && c.name, 30) || ["Primary", "Secondary", "Accent", "Neutral", "Highlight", "Support", "Tint", "Shade"][i], hex: cv.hex } : null;
  }).filter(Boolean);
  const colors = cols.length >= 2 ? cols : cols.concat([{ name: "Ink", hex: "#1f2937" }, { name: "Paper", hex: "#f8f5ef" }]).slice(0, Math.max(2, cols.length + 2));
  const logoSvg = a.logo_svg ? cleanSvg(a.logo_svg) : null;
  if (a.logo_svg && !logoSvg) return err("logo_svg must be an SVG document (starting with <svg).");
  const font = (x, d) => (str(x, 60).replace(/[^A-Za-z0-9 \-]/g, "").trim() || d);
  const spec = { name, tagline: str(a.tagline, 120), colors, fonts: { heading: font(a.heading_font, "Fraunces"), body: font(a.body_font, "Inter") },
    logo: logoSvg ? { svg: logoSvg } : { text: name, font: font(a.heading_font, "Fraunces") },
    layout: MGDBrand.LAYOUTS[a.layout] ? a.layout : "classic", theme: MGDBrand.THEMES[a.theme] ? a.theme : "light", pattern: MGDBrand.PATTERNS[a.pattern] ? a.pattern : "dots" };
  const svg = MGDBrand.boardSvg(spec);
  const info = colors.map((c) => { const i = MGDBrand.colorInfo(c.hex); return `| ${c.name} | \`${i.hex}\` | ${i.rgbCss} | ${i.cmykCss} | \`${i.oklchCss}\` | ${i.on === "#FFFFFF" || i.on === "#ffffff" ? "white" : "black"} text |`; }).join("\n");
  const pairs = MGDBrand.textPairs(colors).slice(0, 6).map((p) => `- ${p.fgName} on ${p.bgName}: ${p.ratio}:1 (${p.level})`).join("\n");
  const q = MGDBrand.handoffQuery(spec);
  const parts = [`Brand board for ${name} (${spec.layout} layout, ${spec.theme}; fonts ${spec.fonts.heading} / ${spec.fonts.body} — Google Fonts, OFL):`,
    "| Colour | HEX | RGB | CMYK (naive, not colour-managed) | OKLCH | On it |\n|---|---|---|---|---|---|\n" + info,
    pairs ? "Contrast-safe text pairs:\n" + pairs : "", fence("svg", svg)];
  if (a.markdown !== false) parts.push("brand.md (give this to an agent or a designer):\n" + fence("markdown", MGDBrand.guidelinesMarkdown(spec)));
  parts.push(`Edit the board and export PNG/PDF: ${T}/brand-board-maker/ · full guidelines PDF: ${T}/brand-guidelines-template/ · website palette: ${T}/website-color-palette-generator/?${q} · DESIGN.md: ${T}/design-md-generator/?${q}`);
  return ok(parts.filter(Boolean).join("\n\n"), { svg, colors: colors.map((c) => ({ ...c, ...MGDBrand.colorInfo(c.hex) })), fonts: spec.fonts, handoff_query: q });
}
function slogans(a) {
  const kw = (Array.isArray(a.keywords) ? a.keywords : str(a.keywords, 200).split(/[,;]+/)).map((k) => str(k, 30).trim()).filter(Boolean).slice(0, 5);
  const brand = str(a.brand, 60).trim();
  if (!brand && !kw.length) return err("Pass a brand name and/or keywords.");
  const inds = MGDSlogan.INDUSTRIES.map((x) => x.key);
  const o = { brand, keywords: kw, industry: inds.includes(a.industry) ? a.industry : "general", tone: MGDSlogan.TONES.map((x) => x.key || x).includes(a.tone) ? a.tone : "friendly",
    length: ["short", "medium", "long", "any"].includes(a.length) ? a.length : "any", count: int(a.count, 20, 1, 60), seed: int(a.seed, 1, 0, 2147483647) };
  let list = MGDSlogan.generate(o);
  if (a.include_brand && brand) list = list.filter((x) => x.hasBrand);
  if (!list.length) return ok(`0 slogans with those settings — drop include_brand or try another tone. Generator: ${T}/slogan-generator/`);
  const text = `${list.length} slogan ideas for ${brand || kw.join(", ")} (${o.industry}, ${o.tone}):\n\n` + list.map((x, i) => `${i + 1}. ${x.text}  (${x.words} words, ${x.chars} chars · ${x.styleName || x.style})`).join("\n") +
    `\n\nOriginal template-based lines; well-known trademarked slogans are filtered out. Before using one commercially, search the trademark registers (USPTO, EUIPO, WIPO) for your class.\nMore, with favourites and a mockup preview: ${T}/slogan-generator/`;
  return ok(text, { slogans: list.map((x) => ({ text: x.text, words: x.words, chars: x.chars, style: x.style, has_brand: !!x.hasBrand })), industry: o.industry, tone: o.tone, seed: o.seed });
}

function lintDesignMd(a) {
  const md = str(a.design_md, 200000);
  if (!md.trim()) return err("Pass design_md (the DESIGN.md text).");
  let r;
  try { r = dmdLint(md); } catch (e) { return err("The linter couldn't parse this file: " + str(e && e.message, 300)); }
  const f = r.findings || [], s = r.summary || {};
  const icon = { error: "❌", warning: "⚠️", info: "ℹ️" };
  const text = `DESIGN.md lint (official @google/design.md 0.4.0 rules): ${s.errors || 0} error(s), ${s.warnings || 0} warning(s), ${s.infos || 0} info.\n\n` +
    (f.length ? f.slice(0, 100).map((x) => `- ${icon[x.severity] || "-"} ${x.severity}${x.path ? ` \`${x.path}\`` : ""}: ${x.message}`).join("\n") : "No findings — the file conforms.") +
    `\n\nGenerate a conformant DESIGN.md: ${T}/design-md-generator/ (or the generate_design_md tool).`;
  return ok(text, { findings: f.slice(0, 200), summary: s, sections: r.sections || [] });
}

// ---------------------------------------------------------------------------------------------------------------------
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools48Tool(name) { return NAMES.has(name); }

export async function callTools48Tool(name, a, env, ctx) {
  a = a || {};
  try {
    if (name === "generate_type_scale") return typeScale(a);
    if (name === "generate_color_scale") return colorScale(a);
    if (name === "check_contrast") return contrast(a);
    if (name === "lint_design_md") return lintDesignMd(a);
    if (name === "convert_color") return convertColor(a);
    if (name === "generate_shadcn_theme") return shadcnTheme(a);
    if (name === "export_design_tokens") return exportTokens(a);
    if (name === "search_icons") return await searchIcons(a);
    if (name === "get_screen_sizes") return screenSizes(a);
    if (name === "make_brand_board") return brandBoard(a);
    if (name === "generate_slogans") return slogans(a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}

